(async()=>{
const R=[["The submission contains one Word document (.docx) named November_Recovery_Exercise_Brief.docx that opens without a repair prompt.", 1], ["The readiness matrix has a row for each of SVC-01 through SVC-12, and every row reports the source criticality and the RTO and RPO targets listed for that service in service_inventory.xlsx.", 3], ["Every service row reports the latest test result, actual recovery minutes, observed loss minutes, and EV evidence ID listed for that service in restore_test_results.xlsx, showing recovery and loss as not measured or blank for SVC-08's not-run test.", 4], ["Every service row reports the dependency validation state and DEP reference listed for that service in dependency_map.xlsx.", 4], ["Every service row reports the open action ID and its current status for each action mapped to that service in resilience_action_log.xlsx, or marks the row as having no open action.", 3], ["Every service row's final decision (Full Failover, Observe Only, or Block) is consistent with that row's readiness evidence and the decision rules CTL-010 through CTL-015 in recovery_exercise_constraints.xlsx.", 4], ["The executive recommendation matches the matrix: SVC-01, SVC-03, SVC-05, SVC-11 and SVC-12 in Full Failover; SVC-07 and SVC-09 Observe Only; SVC-02, SVC-04, SVC-08 and SVC-10 blocked; and SVC-06 either as a provisional Full Failover pending production-equivalent confirmation or as Observe Only until that evidence exists.", 5], ["SVC-02 is blocked because its 41-minute recovery exceeds its 30-minute RTO, DEP-204 is open, and Critical action RA-401 remains open.", 4], ["SVC-04 is blocked because its 118-minute recovery exceeds its 90-minute RTO and High action RA-402 remains open.", 4], ["SVC-08 is blocked because its test was not run, DEP-214 to blocked SVC-04 is open, and RA-403 remains blocked.", 4], ["SVC-10 is blocked because its 390-minute recovery exceeds its 360-minute RTO, DEP-216 is open, and RA-404 remains incomplete.", 4], ["SVC-07 is Observe Only because its passing evidence is a restore sample and RA-405 still requires a full-volume restore.", 3], ["SVC-09 is Observe Only because its passing evidence used a provider sandbox and RA-406 still requires production-throttle confirmation.", 3], ["The wave plan follows the supplied recovery-wave order: SVC-03 in Wave 1; SVC-01, SVC-11, and SVC-12 in Wave 2; SVC-05 in Wave 3, preceded by SVC-06 only if SVC-06 is approved for production failover; and SVC-07 and SVC-09 in the Wave 4 observation lane.", 5], ["The wave plan assigns 3 engineers to Wave 1, 4 to Wave 2, 3 to Wave 3, and 2 to Wave 4.", 4], ["The operating plan keeps production cutovers sequential within each wave.", 3], ["The plan keeps SVC-02 in the primary region and uses validated path DEP-202 for SVC-01.", 4], ["The plan schedules no payment authorization cutover during the 14:00-15:00 UTC blackout (CTL-023).", 4], ["The blocker section links each blocking action to its service and required work, stated or faithfully paraphrased: RA-401 to SVC-02 (restore HSM quorum inside 20 minutes), RA-402 to SVC-04 (reduce DNS TTL and retest regional cutover), RA-403 to SVC-08 (run end-to-end recovery after API retest), and RA-404 to SVC-10 (refresh partner allowlists in recovery region).", 4], ["The blocker section matches the supplied owner, due date, status, and CAB reference for each of RA-401 through RA-404.", 4], ["The brief labels 30 October 2026 as the evidence gate and 8 November 2026 as the exercise date, presenting them as two separate dated items.", 3], ["The operator checklist requires an explicit go or no go decision before the exercise scope is released.", 2], ["The operator checklist requires dependency validation before each service starts.", 2], ["The operator checklist requires start, ready, validation, rollback, and reconciliation times to be recorded for each service, with rollback marked not applicable where no rollback occurs.", 1], ["The operator checklist names the Incident Commander as the rollback authority and lists all three CTL-041 stop conditions: integrity failure, dependency failure, and threatened RTO/RPO.", 1], ["The operator checklist requires the named incident commander and the named rollback authority to be confirmed before execution.", 1], ["The operator checklist requires data and queued work to be reconciled after each wave before the next wave begins.", 1], ["The wave plan schedules a production cutover for SVC-02, SVC-04, SVC-08, or SVC-10", -5], ["The brief invents at least one service, DEP, EV, RA, or CAB identifier that is absent from the supplied files.", -5], ["Each wave in the plan starts inside the UTC wave window that recovery_exercise_constraints.xlsx lists for that wave, and every scheduled item in the wave plan, including the payment blackout hold, falls inside the 10:00-16:00 UTC operating window.", 4], ["The brief states that the recorded recovery times for Wave 2 and Wave 3 exceed those wave windows under the sequential-cutover rule, and gives the exercise-day handling for that conflict rather than presenting the sequence as fitting.", 3], ["The brief flags that SVC-06's passing evidence is a Component failover test and either makes its Full Failover conditional on production-equivalent evidence confirmed by the 2026-10-30 gate or places it in Observe Only pending that evidence.", 3]];
const FILES={input:{name:'recovery_exercise_inputs.zip',b64:''},golden:{name:'November_Recovery_Exercise_Brief.zip',b64:''}};
const REVIEW="This round fixes the four Major findings and three of the four Minor ones without adding criteria. Inputs: recovery_exercise_constraints.xlsx gains CTL-015, which makes a passing Component failover test support only a provisional Full failover call that falls to Observe Only without production-equivalent confirmation by the decision gate; restore_test_results.xlsx now leaves SVC-08's recovery and loss minutes blank because the test was not run. Rubric: the cohort, wave-order and SVC-06 criteria now accept either the provisional Full failover reading or Observe Only pending evidence; the blocker criterion binds RA-401 to RA-404 to their services and required work; the evidence-capture checklist criterion requires all five per-service times with rollback not applicable where none occurs; the rollback criterion requires the Incident Commander and all three CTL-041 stop conditions; the matrix test criterion accepts not measured for SVC-08; the row-label criterion was merged into the service_inventory row check, the decision criterion now requires decisions consistent with the evidence and CTL rules, and the file criterion was reduced to weight 1. Golden: the matrix marks SVC-06 Full (provisional) and SVC-08 not measured, the SVC-06 note cites CTL-015, and the checklist records the five times per service. The concise-narrative Minor was not given a separate criterion to keep the rubric from growing. The prompt is unchanged.";
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const txt=e=>(e.textContent||'').replace(/\s+/g,' ').trim();
const setv=(el,v)=>{const p=el instanceof HTMLTextAreaElement?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;el.focus();Object.getOwnPropertyDescriptor(p,'value').set.call(el,String(v));el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));el.blur();};
// ---------- 1. uploads ----------
const toFile=f=>{const bin=atob(f.b64);const a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);return new File([a],f.name,{type:'application/zip'});};
const near=(el,re,stop)=>{let c=el;for(let k=0;k<8&&c;k++){c=c.parentElement;if(c&&re.test(txt(c))&&!(stop&&stop.test(txt(c))))return c;}return null;};
const fileInputs=[...document.querySelectorAll('input[type=file]')];
const upload=async(el,f,label)=>{if(!el){console.error('Uploader not found:',label);return;}const dt=new DataTransfer();dt.items.add(toFile(f));el.files=dt.files;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));const z=el.closest('div');try{z&&z.dispatchEvent(new DragEvent('drop',{bubbles:true,cancelable:true,dataTransfer:dt}));}catch(e){}console.log('Uploaded',f.name,'->',label);await sleep(2500);};
await upload(fileInputs.find(i=>near(i,/Input File Uploader/i,/Golden Solution File Uploader/i)),FILES.input,'Input File Uploader');
await upload(fileInputs.find(i=>near(i,/Golden Solution File Uploader/i,/Input File Uploader/i)),FILES.golden,'Golden Solution File Uploader');
// ---------- 2. multi-modal = No ----------
const q=[...document.querySelectorAll('body *')].find(e=>/^Are the input files multi-modal\?/i.test(txt(e))&&e.children.length<3);
let blk=q;while(blk&&!blk.querySelector('input[type=radio],[role=radio]'))blk=blk.parentElement;
if(blk){const r=[...blk.querySelectorAll('input[type=radio]')].find(x=>/^no$/i.test(x.value)||(x.closest('label')&&txt(x.closest('label'))==='No'));const o=[...blk.querySelectorAll('label,[role=radio],button,div,span')].filter(e=>txt(e)==='No');(r||o[o.length-1]).click();console.log('Multi-modal -> No');}else console.error('Multi-modal question not found');
// ---------- 3. rubric ----------
const isHead=e=>/^Criterion ?\d+$/.test(txt(e));
const delBtns=c=>[...c.querySelectorAll('button')].filter(b=>/delete section/i.test(b.textContent));
const inForm=e=>{let c=e;for(let k=0;k<5&&c;k++){c=c.parentElement;if(c&&delBtns(c).length===1)return true;}return false;};
const heads=()=>[...document.querySelectorAll('body *')].filter(e=>isHead(e)&&![...e.children].some(isHead)&&inForm(e));
const addBtn=()=>[...document.querySelectorAll('button')].find(b=>/add criterion/i.test(b.textContent));
const box=h=>{let c=h.parentElement;while(c&&!c.querySelector('textarea'))c=c.parentElement;return c;};
const own=c=>c&&heads().filter(x=>c.contains(x)).length===1&&delBtns(c).length<=1;
console.log('Criterion slots before:',heads().length);
for(let i=0;i<R.length;i++){
  let t=0;while(heads().length<i+1&&t++<10){const b=addBtn();if(!b){console.error('Add criterion button not found');return;}b.scrollIntoView({block:'center'});b.click();await sleep(700);}
  if(heads().length<i+1){console.error('Could not create criterion',i+1);return;}
  let h=heads()[i];h.scrollIntoView({block:'center'});let c=box(h);
  if(!own(c)){h.click();await sleep(600);h=heads()[i];c=box(h);}
  if(!own(c)){console.error('Could not open criterion',i+1);return;}
  const ta=c.querySelector('textarea');const w=[...c.querySelectorAll('input')].find(x=>!['checkbox','radio','file','hidden','button','submit'].includes(x.type));
  setv(ta,R[i][0]);if(w)setv(w,R[i][1]);await sleep(250);
  console.log('Criterion',i+1,ta.value===R[i][0]?'text ok':'TEXT NOT SET',w&&String(w.value)===String(R[i][1])?'weight ok':'CHECK WEIGHT');
}
// ---------- 4. review ----------
const hd=[...document.querySelectorAll('body *')].find(e=>/^Briefly summarize the changes made/i.test(txt(e))&&e.children.length<3);
let rb=hd;while(rb&&!rb.querySelector('textarea'))rb=rb.parentElement;
if(rb){const ta=rb.querySelector('textarea');setv(ta,REVIEW);console.log('Review',ta.value===REVIEW?'filled':'NOT SET');}else console.error('Review box not found');
console.log('ALL DONE. Criteria on page: '+heads().length+' (should be 32). Check both uploads show a file name.');
})();